--[[ AETHER | TINY SKIES AIR COMBAT V1.0
  Standalone encoded Lua release. Source available alongside this file.
  Enemy ESP and aim support; Silent Aim experimental client raycast hook only.
]]
return (function()
    local hex=table.concat({
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    })
    local bytes={}
    local k=0
    for i=1,#hex,2 do
        k=k+1
        bytes[k]=string.char((tonumber(hex:sub(i,i+1),16)-43-((k*17)%251))%256)
    end
    local load,err=(loadstring or load)(table.concat(bytes))
    if not load then error("AETHER failed to load: "..tostring(err)) end
    return load()
end)()
